"""Optional step-level lineage manifest for one pipeline run.

The lineage manifest is a self-contained, hash-chained summary of a run: it
needs no logs or stored files to explain which inputs, parameters and
intermediate steps produced a result. Every record's ``sha256`` is computed
over the canonical JSON of all its other fields, with each record covering the
previous one, so any tampering is detectable by :func:`verify_lineage`.

Canonical JSON means ``json.dumps(value, ensure_ascii=False,
separators=(",", ":"), sort_keys=True)``: object keys sorted by Unicode code
point, arrays in order, no insignificant whitespace, numbers/booleans/null in
their native JSON types.
"""

from __future__ import annotations

import copy
import hashlib
import json
import re
from typing import Any, Callable

GENESIS_SHA256 = "0" * 64

_STEP_FIELDS = ("input_sha256", "name", "output_sha256", "params", "previous_sha256")
_MANIFEST_FIELDS = ("final_sha256", "input_sha256", "params", "steps")
_HEX64 = re.compile(r"[0-9a-f]{64}\Z")
_JSON_TYPES = (dict, list, str, int, float, bool, type(None))


def canonical(value: Any) -> str:
    """Stable JSON rendering: sorted keys, no insignificant whitespace."""
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"), sort_keys=True)


def digest(value: Any) -> str:
    """SHA-256 of the canonical JSON rendering of ``value``."""
    return hashlib.sha256(canonical(value).encode("utf-8")).hexdigest()


def digest_text(text: str) -> str:
    """SHA-256 of raw UTF-8 text (the run input, kept verbatim)."""
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def json_snapshot(value: Any) -> Any:
    """Deep-copy ``value`` and prove every leaf is representable as JSON.

    Raises ``TypeError`` for values JSON cannot represent (including booleans
    are fine but sets, tuples, custom objects or NaN/Infinity are not). The
    returned object is fully detached from ``value``: later mutation of the
    caller's objects can never reach the snapshot.
    """
    if isinstance(value, bool) or value is None or isinstance(value, (str, int)):
        return value
    if isinstance(value, float):
        if not value <= value or value in (float("inf"), float("-inf")):
            raise TypeError("lineage params must contain only JSON-representable values")
        return value
    if isinstance(value, dict):
        result: dict[str, Any] = {}
        for key, item in value.items():
            if not isinstance(key, str):
                raise TypeError("lineage params object keys must be strings")
            result[key] = json_snapshot(item)
        return result
    if isinstance(value, list):
        return [json_snapshot(item) for item in value]
    raise TypeError("lineage params must contain only JSON-representable values")


def record(
    name: str,
    params: Any,
    input_sha256: str,
    output_sha256: str,
    previous_sha256: str,
) -> dict[str, Any]:
    """Build one lineage record and hash everything except its own digest."""
    body: dict[str, Any] = {
        "name": name,
        "params": params,
        "input_sha256": input_sha256,
        "output_sha256": output_sha256,
        "previous_sha256": previous_sha256,
    }
    return {**body, "sha256": digest(body)}


def build_manifest(
    vcf_text: str,
    params_snapshot: Any,
    emit: Callable[[list[dict[str, Any]]], None],
) -> dict[str, Any]:
    """Assemble a manifest; ``emit`` appends the executed steps in order.

    Only steps that actually execute must be appended by ``emit``; steps
    skipped by a condition must not appear in the list.
    """
    steps: list[dict[str, Any]] = []
    emit(steps)
    if not steps:
        raise ValueError("lineage requires at least one executed step")
    return {
        "input_sha256": digest_text(vcf_text),
        "params": params_snapshot,
        "steps": steps,
        "final_sha256": steps[-1]["sha256"],
    }


def _is_hex64(value: Any) -> bool:
    return isinstance(value, str) and bool(_HEX64.fullmatch(value))


def _check_json_shape(value: Any) -> None:
    """Structural validation only; rejects types JSON round-tripping cannot."""
    if isinstance(value, bool) or value is None or isinstance(value, (str, int)):
        return
    if isinstance(value, float):
        if not value <= value or value in (float("inf"), float("-inf")):
            raise ValueError("lineage fields must contain only JSON-representable values")
        return
    if isinstance(value, dict):
        for key, item in value.items():
            if not isinstance(key, str):
                raise ValueError("lineage fields must use string object keys")
            _check_json_shape(item)
        return
    if isinstance(value, list):
        for item in value:
            _check_json_shape(item)
        return
    raise ValueError("lineage fields must contain only JSON-representable values")


def verify_lineage(lineage: Any) -> bool:
    """Recompute a lineage manifest chain; return ``True`` only when intact.

    Structural problems (not a dict, a missing/extra/unknown field, a digest
    that is not 64 lowercase hex characters) raise ``ValueError``. A fully
    well-shaped but inconsistent manifest returns ``False``: a tampered field,
    reordered or missing record, a wrong chain head, or a bad ``final_sha256``.
    The passed object is never modified.
    """
    if not isinstance(lineage, dict):
        raise ValueError("lineage must be an object")
    if set(lineage) != set(_MANIFEST_FIELDS):
        raise ValueError("lineage object has missing or unknown fields")

    steps = lineage["steps"]
    if not isinstance(steps, list) or not steps:
        raise ValueError("lineage steps must be a non-empty array")

    expected_previous = GENESIS_SHA256
    for index, entry in enumerate(steps):
        if not isinstance(entry, dict) or set(entry) != set(_STEP_FIELDS) | {"sha256"}:
            raise ValueError(f"lineage step {index} has missing or unknown fields")
        if not isinstance(entry["name"], str) or not entry["name"]:
            raise ValueError(f"lineage step {index} name must be a non-empty string")
        for field in ("input_sha256", "output_sha256", "previous_sha256", "sha256"):
            if not _is_hex64(entry[field]):
                raise ValueError(f"lineage step {index} {field} must be 64 lowercase hex characters")
        _check_json_shape(entry["params"])
        if entry["previous_sha256"] != expected_previous:
            return False
        body = {field: entry[field] for field in _STEP_FIELDS}
        if digest(body) != entry["sha256"]:
            return False
        expected_previous = entry["sha256"]

    params = lineage["params"]
    _check_json_shape(params)
    if not _is_hex64(lineage["input_sha256"]):
        raise ValueError("lineage input_sha256 must be 64 lowercase hex characters")
    if not _is_hex64(lineage["final_sha256"]):
        raise ValueError("lineage final_sha256 must be 64 lowercase hex characters")
    if lineage["final_sha256"] != steps[-1]["sha256"]:
        return False
    return True

from __future__ import annotations

import math
from typing import Any

from .annotate import annotate, table_sha256
from .errors import ValidationError
from .provenance import digest, digest_text, step
from .recordfilter import evaluate_record_filter, normalize_record_filter

PARSER_VERSION = "variantrail-vcf-1"
ALLOWED_IMPACTS = ("HIGH", "LOW", "MODERATE", "MODIFIER", "UNKNOWN")
RECORD_FILTER_REASONS = ("dp_below_min", "not_pass", "qual_below_min")
RULE_MISMATCH = "rule_mismatch"


def normalize_params(raw: Any) -> dict[str, Any]:
    """Validate run parameters and fill every documented default."""
    if raw is None:
        raw = {}
    if not isinstance(raw, dict):
        raise ValidationError("params must be an object")
    unknown = sorted(set(raw) - {"genes", "impacts", "min_dp", "min_qual", "pass_only", "record_filter"})
    if unknown:
        raise ValidationError(f"params contains unknown fields: {', '.join(unknown)}")

    params: dict[str, Any] = {"genes": [], "impacts": [], "min_dp": 0, "min_qual": 0.0, "pass_only": False}
    if "min_qual" in raw:
        value = raw["min_qual"]
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value < 0:
            raise ValidationError("params.min_qual must be a non-negative finite number")
        params["min_qual"] = float(value)
    if "min_dp" in raw:
        value = raw["min_dp"]
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValidationError("params.min_dp must be a non-negative integer")
        params["min_dp"] = value
    if "pass_only" in raw:
        if not isinstance(raw["pass_only"], bool):
            raise ValidationError("params.pass_only must be a boolean")
        params["pass_only"] = raw["pass_only"]
    for key in ("genes", "impacts"):
        if key not in raw:
            continue
        value = raw[key]
        if not isinstance(value, list) or any(not isinstance(item, str) or not item for item in value):
            raise ValidationError(f"params.{key} must be an array of non-empty strings")
        if len(set(value)) != len(value):
            raise ValidationError(f"params.{key} must not contain duplicate values")
        params[key] = sorted(value)
    for impact in params["impacts"]:
        if impact not in ALLOWED_IMPACTS:
            raise ValidationError(f"params.impacts entry {impact} is not one of {', '.join(ALLOWED_IMPACTS)}")
    if "record_filter" in raw:
        params["record_filter"] = normalize_record_filter(raw["record_filter"])
    return params


def execute(parsed: dict[str, Any], vcf_text: str, params: dict[str, Any]) -> dict[str, Any]:
    """Run ingest -> filter -> annotate -> summarize and record each link."""
    steps: list[dict[str, Any]] = []

    records = parsed["records"]
    steps.append(
        step(
            1,
            "ingest",
            {"parser_version": PARSER_VERSION},
            digest_text(vcf_text),
            digest({"records": records}),
            None,
        )
    )

    reasons = list(RECORD_FILTER_REASONS)
    expression = params.get("record_filter")
    if expression is not None:
        reasons.append(RULE_MISMATCH)
    counts = dict.fromkeys(reasons, 0)
    kept: list[dict[str, Any]] = []
    for record in records:
        reason = record_reason(record, params)
        if reason is None:
            kept.append(record)
        else:
            counts[reason] += 1
    filter_params: dict[str, Any] = {
        "min_dp": params["min_dp"],
        "min_qual": params["min_qual"],
        "pass_only": params["pass_only"],
    }
    if expression is not None:
        filter_params["record_filter"] = expression
    steps.append(
        step(
            2,
            "filter",
            filter_params,
            steps[-1]["output_sha256"],
            digest({"filter_counts": counts, "records": kept}),
            steps[-1]["hash"],
        )
    )

    variants: list[dict[str, Any]] = []
    filtered = 0
    for record in kept:
        annotations = [entry for entry in annotate(record) if allele_selected(entry, params)]
        if not annotations:
            filtered += 1
            continue
        variants.append(variant_document(record, annotations))
    counts = {**counts, "allele_filtered": filtered}
    steps.append(
        step(
            3,
            "annotate",
            {
                "annotation_table_sha256": table_sha256(),
                "genes": params["genes"],
                "impacts": params["impacts"],
            },
            steps[-1]["output_sha256"],
            digest({"filter_counts": counts, "variants": variants}),
            steps[-1]["hash"],
        )
    )

    statistics = summarize(records, variants, counts)
    steps.append(step(4, "summarize", {}, steps[-1]["output_sha256"], digest(statistics), steps[-1]["hash"]))

    return {"filter_counts": counts, "provenance": steps, "statistics": statistics, "variants": variants}


def record_reason(record: dict[str, Any], params: dict[str, Any]) -> str | None:
    """First failing record-level filter, in the documented precedence order."""
    if params["pass_only"] and record["filter"] != ["PASS"]:
        return "not_pass"
    if record["qual"] is None:
        if params["min_qual"] > 0:
            return "qual_below_min"
    elif record["qual"] < params["min_qual"]:
        return "qual_below_min"
    if record["dp"] is None:
        if params["min_dp"] > 0:
            return "dp_below_min"
    elif record["dp"] < params["min_dp"]:
        return "dp_below_min"
    expression = params.get("record_filter")
    if expression is not None and not evaluate_record_filter(expression, record):
        return RULE_MISMATCH
    return None


def allele_selected(annotation: dict[str, Any], params: dict[str, Any]) -> bool:
    """Allele-level allowlists, applied after annotation."""
    if params["genes"] and annotation["gene"] not in params["genes"]:
        return False
    if params["impacts"] and annotation["impact"] not in params["impacts"]:
        return False
    return True


def variant_document(record: dict[str, Any], annotations: list[dict[str, Any]]) -> dict[str, Any]:
    return {
        "alts": list(record["alts"]),
        "annotations": annotations,
        "chrom": record["chrom"],
        "dp": record["dp"],
        "filter": list(record["filter"]),
        "id": record["id"],
        "info": dict(record["info"]),
        "line": record["line"],
        "pos": record["pos"],
        "qual": record["qual"],
        "raw": record["raw"],
        "ref": record["ref"],
    }


def summarize(
    records: list[dict[str, Any]],
    variants: list[dict[str, Any]],
    counts: dict[str, int],
) -> dict[str, Any]:
    consequence_counts: dict[str, int] = {}
    gene_counts: dict[str, int] = {}
    impact_counts: dict[str, int] = {}
    alleles_kept = 0
    for variant in variants:
        for annotation in variant["annotations"]:
            alleles_kept += 1
            _bump(consequence_counts, annotation["consequence"])
            _bump(gene_counts, annotation["gene"] or "NA")
            _bump(impact_counts, annotation["impact"])
    return {
        "alleles_kept": alleles_kept,
        "alleles_total": sum(len(record["alts"]) for record in records),
        "consequence_counts": _ordered(consequence_counts),
        "filter_counts": _ordered(counts),
        "gene_counts": _ordered(gene_counts),
        "impact_counts": _ordered(impact_counts),
        "records_filtered": len(records) - len(variants),
        "records_kept": len(variants),
        "records_total": len(records),
    }


def _bump(counts: dict[str, int], key: str) -> None:
    counts[key] = counts.get(key, 0) + 1


def _ordered(counts: dict[str, int]) -> dict[str, int]:
    return {key: counts[key] for key in sorted(counts)}

